  \node[above] at (ptM) {$M$};
  \node[below left] at (ptN) {$N$};
  \node[below right] at (ptP) {$P$};
  \node[below, font=\small] at (0,-1.3) {a)};
  \begin{scope}[xshift=4.2cm]
    \coordinate (sD) at (0,1.7);
    \coordinate (sE) at (-1.3,-0.5);
